import { createHashRouter, Navigate } from 'react-router-dom';
import Home from '../pages/home';
import Team from '../pages/team';
import Main from '../pages/main';  // 注意：你写成了 main.js，应该是 main（或 Main）

const routes = [
  {
    path: "/",                    // GitHub Pages 的根路径
    element: <Main />,
    children: [
      {
        index: true,              // 访问 / 时默认显示 Home
        element: <Home />,
      },
      {
        path: "home",             // /home → Home 页面
        element: <Home />,
      },
      {
        path: "team",             // /team → Team 页面
        element: <Team />,
      },
      {
        path: "*",                // 任意其他路径，都重定向到 Home（防止 404）
        element: <Navigate to="/home" replace />,
      },
    ],
  },
];

export default createHashRouter(routes);